using System.Data;
using Microsoft.Data.SqlClient;
namespace AgriFlow.Data;
public sealed record BuyerOrderRow(int OrderId,string CropName,decimal Quantity,string Unit,decimal UnitPrice,decimal TotalAmount,string Status,string FarmerName,string FarmName,DateTime CreatedAt);
public sealed record BuyerInvoiceRow(int OrderId,string InvoiceNumber,string CropName,decimal Quantity,string Unit,decimal TotalAmount,string Status,DateTime CreatedAt);
public sealed class BuyerRepository
{
 private readonly DbConnectionFactory _db;
 public BuyerRepository(DbConnectionFactory db)=>_db=db;
 public async Task<int> PlaceOrderAsync(int buyerId,int listingId,decimal quantity,string deliveryAddress="To be confirmed")
 {
  if(quantity<=0) throw new InvalidOperationException("Order quantity must be greater than zero.");
  await using var c=_db.CreateConnection(); await c.OpenAsync(); await using var t=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable);
  try {
   int businessId; await using(var q=new SqlCommand("SELECT BuyerBusinessId FROM app_user WHERE Id=@BuyerId AND Role='Buyer'",c,t)){q.Parameters.Add("@BuyerId",SqlDbType.Int).Value=buyerId;var v=await q.ExecuteScalarAsync();if(v is null||v==DBNull.Value)throw new InvalidOperationException("Your buyer business profile was not found.");businessId=Convert.ToInt32(v);}
   await using(var q=new SqlCommand("UPDATE listing SET AvailableQty=AvailableQty-@Qty,ReservedQty=ReservedQty+@Qty,UpdatedAt=SYSUTCDATETIME() WHERE Id=@Id AND Status='Available' AND OpenForReservation=1 AND AvailableQty>=@Qty",c,t)){q.Parameters.Add("@Id",SqlDbType.Int).Value=listingId;q.Parameters.Add("@Qty",SqlDbType.Decimal).Value=quantity;if(await q.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("This listing does not have enough quantity or is no longer available.");}
   decimal price;await using(var q=new SqlCommand("SELECT PricePerUnit FROM listing WHERE Id=@Id",c,t)){q.Parameters.Add("@Id",SqlDbType.Int).Value=listingId;price=Convert.ToDecimal(await q.ExecuteScalarAsync());}
   int orderId;await using(var q=new SqlCommand("INSERT INTO orders(OrderNumber,BuyerBusinessId,PlacedByUserId,DeliveryAddress,Status,TotalAmount) OUTPUT INSERTED.Id VALUES(@Number,@BusinessId,@BuyerId,@Address,'Placed',@Total)",c,t)){q.Parameters.Add("@Number",SqlDbType.NVarChar,20).Value="AF-"+Guid.NewGuid().ToString("N")[..8].ToUpperInvariant();q.Parameters.Add("@BusinessId",SqlDbType.Int).Value=businessId;q.Parameters.Add("@BuyerId",SqlDbType.Int).Value=buyerId;q.Parameters.Add("@Address",SqlDbType.NVarChar,250).Value=deliveryAddress;q.Parameters.Add("@Total",SqlDbType.Decimal).Value=quantity*price;orderId=Convert.ToInt32(await q.ExecuteScalarAsync());}
   await using(var q=new SqlCommand("INSERT INTO order_item(OrderId,ListingId,QtyRequested,UnitPrice,Status,ReservedAt) VALUES(@OrderId,@ListingId,@Qty,@Price,'Reserved',SYSUTCDATETIME())",c,t)){q.Parameters.Add("@OrderId",SqlDbType.Int).Value=orderId;q.Parameters.Add("@ListingId",SqlDbType.Int).Value=listingId;q.Parameters.Add("@Qty",SqlDbType.Decimal).Value=quantity;q.Parameters.Add("@Price",SqlDbType.Decimal).Value=price;await q.ExecuteNonQueryAsync();}
   await t.CommitAsync();return orderId;
  }catch{await t.RollbackAsync();throw;}
 }
 public async Task<IReadOnlyList<BuyerOrderRow>> GetOrdersAsync(int buyerId){const string s="SELECT o.Id,c.Name,oi.QtyRequested,l.Unit,oi.UnitPrice,o.TotalAmount,o.Status,u.FullName,fp.FarmName,o.CreatedAt FROM orders o JOIN order_item oi ON oi.OrderId=o.Id JOIN listing l ON l.Id=oi.ListingId JOIN crop c ON c.Id=l.CropId JOIN app_user u ON u.Id=l.FarmerId JOIN farmer_profile fp ON fp.UserId=l.FarmerId WHERE o.PlacedByUserId=@Id ORDER BY o.CreatedAt DESC";var r=new List<BuyerOrderRow>();await using var c=_db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand(s,c);q.Parameters.Add("@Id",SqlDbType.Int).Value=buyerId;await using var x=await q.ExecuteReaderAsync();while(await x.ReadAsync())r.Add(new BuyerOrderRow(x.GetInt32(0),x.GetString(1),x.GetDecimal(2),x.GetString(3),x.GetDecimal(4),x.GetDecimal(5),x.GetString(6),x.GetString(7),x.GetString(8),x.GetDateTime(9)));return r;}
 public async Task<IReadOnlyList<BuyerInvoiceRow>> GetInvoicesAsync(int buyerId){const string s="SELECT o.Id,i.InvoiceNumber,c.Name,ISNULL(oi.QtyAccepted,oi.QtyRequested),l.Unit,i.Amount,i.Status,o.CreatedAt FROM invoice i JOIN orders o ON o.Id=i.OrderId JOIN order_item oi ON oi.OrderId=o.Id JOIN listing l ON l.Id=oi.ListingId JOIN crop c ON c.Id=l.CropId WHERE o.PlacedByUserId=@Id ORDER BY i.IssuedAt DESC";var r=new List<BuyerInvoiceRow>();await using var c=_db.CreateConnection();await c.OpenAsync();await using var q=new SqlCommand(s,c);q.Parameters.Add("@Id",SqlDbType.Int).Value=buyerId;await using var x=await q.ExecuteReaderAsync();while(await x.ReadAsync())r.Add(new BuyerInvoiceRow(x.GetInt32(0),x.GetString(1),x.GetString(2),x.GetDecimal(3),x.GetString(4),x.GetDecimal(5),x.GetString(6),x.GetDateTime(7)));return r;}
 public async Task PayInvoiceAsync(int buyerId,int orderId){await using var c=_db.CreateConnection();await c.OpenAsync();await using var t=(SqlTransaction)await c.BeginTransactionAsync();try{const string s="UPDATE i SET Status='Paid',PaidAt=SYSUTCDATETIME(),PaymentMethod='Mobile money (simulated)',PaymentReference=@Ref FROM invoice i JOIN orders o ON o.Id=i.OrderId WHERE i.OrderId=@OrderId AND o.PlacedByUserId=@BuyerId AND i.Status='Unpaid';";await using(var q=new SqlCommand(s,c,t)){q.Parameters.Add("@OrderId",SqlDbType.Int).Value=orderId;q.Parameters.Add("@BuyerId",SqlDbType.Int).Value=buyerId;q.Parameters.Add("@Ref",SqlDbType.NVarChar,60).Value="SIM-"+Guid.NewGuid().ToString("N")[..10].ToUpperInvariant();if(await q.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("This invoice is not ready for payment.");}await using(var q=new SqlCommand("UPDATE orders SET Status='Paid',UpdatedAt=SYSUTCDATETIME() WHERE Id=@OrderId AND PlacedByUserId=@BuyerId",c,t)){q.Parameters.Add("@OrderId",SqlDbType.Int).Value=orderId;q.Parameters.Add("@BuyerId",SqlDbType.Int).Value=buyerId;await q.ExecuteNonQueryAsync();}await t.CommitAsync();}catch{await t.RollbackAsync();throw;}}
}